export interface SongMetadata {
  id: string;
  name: string;
  artist: string;
  album?: string;
  year: number;
  genre: string;
  era: string;
  difficulty: 'easy' | 'medium' | 'hard' | 'expert';
  notes: string[];
  extendedNotes: string[];
  hint: string;
  trivia: string;
  spotifyId?: string;
  appleMusicId?: string;
  youtubeId?: string;
  coverArt?: string;
  tags: string[];
  popularity: number;
  bpm?: number;
  key?: string;
}

export interface ArtistDiscography {
  title: string;
  year: number;
  type: 'album' | 'single' | 'ep';
  coverUrl?: string;
  spotifyId?: string;
}

export interface TourDate {
  date: string;
  venue: string;
  city: string;
  country: string;
  ticketUrl?: string;
}

export interface ArtistMilestone {
  year: number;
  event: string;
  description: string;
}

export interface ArtistInfo {
  name: string;
  spotifyUrl?: string;
  appleMusicUrl?: string;
  youtubeUrl?: string;
  soundCloudUrl?: string;
  tidalUrl?: string;
  amazonMusicUrl?: string;
  websiteUrl?: string;
  bio?: string;
  genres: string[];
  imageUrl?: string;
  // Extended info
  fullBio?: string;
  monthlyListeners?: string;
  followers?: string;
  socialMedia?: {
    instagram?: string;
    twitter?: string;
    tiktok?: string;
    facebook?: string;
  };
  discography?: ArtistDiscography[];
  tourDates?: TourDate[];
  merchUrl?: string;
  fanFacts?: string[];
  timeline?: ArtistMilestone[];
  similarArtists?: string[];
  awards?: string[];
  originCountry?: string;
  activeYears?: string;
  recordLabel?: string;
}

